/* -------------------------------------------------------------------- */
/*  Header (page-based navigation)                                       */
/* -------------------------------------------------------------------- */

function Header({ page, goTo }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 inset-x-0 z-50 transition-colors duration-300 ${
        scrolled
          ? "bg-slate-950/80 backdrop-blur-md border-b border-slate-800"
          : "bg-transparent border-b border-transparent"
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
        <button onClick={() => goTo("home")} aria-label="Zur Startseite">
          <Logo />
        </button>

        <nav className="hidden md:flex items-center gap-9">
          {PAGES.map((p) => (
            <button
              key={p.id}
              onClick={() => goTo(p.id)}
              className={`relative text-sm transition-colors group ${
                page === p.id ? "text-slate-50" : "text-slate-300 hover:text-slate-50"
              }`}
            >
              {p.label}
              <span
                className={`absolute left-0 -bottom-1 h-px bg-blue-400 transition-all duration-300 ${
                  page === p.id ? "w-full" : "w-0 group-hover:w-full"
                }`}
              />
            </button>
          ))}
        </nav>

        <button
          onClick={() => goTo("kontakt")}
          className="hidden md:inline-flex items-center gap-2 rounded-full bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium px-5 py-2.5 transition-colors"
        >
          Transport anfragen
          <ArrowRight className="w-4 h-4" />
        </button>

        <button className="md:hidden text-slate-100" onClick={() => setOpen((v) => !v)} aria-label="Menü öffnen">
          {open ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.25 }}
            className="md:hidden overflow-hidden bg-slate-950/95 backdrop-blur-md border-b border-slate-800"
          >
            <div className="px-6 py-5 flex flex-col gap-4">
              {PAGES.map((p) => (
                <button
                  key={p.id}
                  onClick={() => {
                    setOpen(false);
                    goTo(p.id);
                  }}
                  className={`text-left text-base py-1 ${page === p.id ? "text-blue-400" : "text-slate-200"}`}
                >
                  {p.label}
                </button>
              ))}
              <button
                onClick={() => {
                  setOpen(false);
                  goTo("kontakt");
                }}
                className="mt-2 inline-flex items-center justify-center gap-2 rounded-full bg-blue-600 text-white text-sm font-medium px-5 py-3"
              >
                Transport anfragen <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

