/* -------------------------------------------------------------------- */
/*  Truck scroll section                                                 */
/* -------------------------------------------------------------------- */

function TruckScrollSection() {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end end"] });

  const x = useTransform(scrollYProgress, [0, 1], ["-45vw", "115vw"]);
  const wheelRotate = useTransform(scrollYProgress, [0, 1], [0, 1440]);
  const headlineOpacity = useTransform(scrollYProgress, [0, 0.15, 0.85, 1], [0, 1, 1, 0]);
  const markX = useTransform(scrollYProgress, [0, 1], ["0%", "-200%"]);

  return (
    <section ref={ref} className="relative h-[260vh] bg-slate-950">
      <div className="sticky top-0 h-screen overflow-hidden flex items-center">
        <motion.div
          style={{ opacity: reduce ? 1 : headlineOpacity }}
          className="absolute inset-0 flex flex-col items-center justify-center text-center px-6"
        >
          <span className="text-[13vw] md:text-[9vw] font-semibold tracking-tight text-slate-800/70 select-none leading-none">
            ON&nbsp;THE&nbsp;ROAD
          </span>
          <span className="mt-4 text-lg md:text-2xl text-slate-300 font-medium">
            Direkt. Flexibel. Zuverlässig.
          </span>
        </motion.div>

        <div className="absolute bottom-[16%] left-0 right-0 h-24 bg-gradient-to-b from-slate-900 to-slate-950 border-t border-slate-800">
          <div className="absolute inset-0 overflow-hidden">
            <motion.div
              style={{ x: reduce ? "0%" : markX }}
              className="absolute top-1/2 -translate-y-1/2 flex gap-16 w-[300%]"
            >
              {Array.from({ length: 24 }).map((_, i) => (
                <span
                  key={i}
                  className="h-1.5 w-16 rounded-full bg-cyan-400/60 shadow-[0_0_12px_2px_rgba(56,189,248,0.4)]"
                />
              ))}
            </motion.div>
          </div>
        </div>

        <motion.div style={{ x: reduce ? "10vw" : x }} className="absolute bottom-[20%] left-0">
          <SemiTruckSVG wheelRotate={wheelRotate} />
        </motion.div>
      </div>
    </section>
  );
}

